import ast

def check_node(node):
    if isinstance(node, (ast.Expression, ast.BoolOp, ast.UnaryOp, ast.Compare, ast.Constant, ast.Name)):
        if isinstance(node, ast.BoolOp):
            return all(check_node(v) for v in node.values)
        if isinstance(node, ast.UnaryOp):
            return isinstance(node.op, ast.Not) and check_node(node.operand)
        if isinstance(node, ast.Compare):
            # Check ops
            for op in node.ops:
                if not isinstance(op, (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)):
                    return False
            # Check left and comparators
            if not check_node(node.left):
                return False
            for comp in node.comparators:
                if not check_node(comp):
                    return False
            return True
        if isinstance(node, ast.Name):
            return node.id in ['id', 'name', 'email']
        if isinstance(node, ast.Constant):
            return isinstance(node.value, (int, str))
        if isinstance(node, ast.Expression):
